SELECT molecule_dictionary.chembl_id AS molecule_chembl_id, molecule_dictionary.pref_name AS molecule_name, molecule_dictionary.max_phase, molecule_dictionary.molecule_type, compound_structures.canonical_smiles FROM docs, compound_records, molecule_dictionary, compound_structures WHERE docs.doc_id = compound_records.doc_id AND compound_records.molregno = molecule_dictionary.molregno AND molecule_dictionary.molregno = compound_structures.molregno AND docs.chembl_id = 'CHEMBL1126800' ORDER BY molecule_chembl_id ASC
